G=load()
def solve(g, dbg=False):
    h=len(g); w=len(g[0]); out=[r[:] for r in g]
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    cand=[c for c in others if 1<=cnt[c]<=6]
    print(dbg,'counts',{c:cnt[c] for c in others},'bg',bg,'cand',cand)
    marker=min(cand,key=lambda c:cnt[c]) if cand else None
    pts=sorted((r,c) for r in range(h) for c in range(w) if g[r][c]==marker) if marker else []
    # pick a diagonal direction consistent with pts collinearity; try both orientations
    res=[]
    for slope,ds in [(-1,1),(1,-1),(-1,-1),(1,1)]:
        segs=[]
        cur=None; prev=None
        for p in sorted(pts):
            if cur is None or abs(p[0]-cur)+abs(p[1]-cur[0])==abs(p[0]+slope*p[1]-(cur[0]+slope*cur[1])):
                cur=p; segs.append(cur)
        if len(segs)>=2: continue
        v=(ds, ds)  # perpendicular to chosen slope
        for n in [(pts[0][0]+v[0],pts[0][1]+v[1]),(pts[-1][0]-v[0],pts[-1][1]-v[1])]:
            if not(0<=n[0]<h and 0<=n[1]<w) or g[n[0]][n[1]]!=bg: continue
            for q in [(v[1],v[0]),(-v[1],-v[0])]:
                rr,cc=n[0]+q[0],n[1]+q[1]; seg=[]
                while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
                    seg.append((rr,cc)); rr+=q[0]; cc+=q[1]
                if seg: res.append(seg)
    if dbg: print('segments:',res)
    best=max(res,key=len)
    for r,c in best: out[r][c]=3
    return out
for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    solve(G[k+' input'],dbg=True)

